import {WORLD_TASKS,modularWorldConfig,taskEnabled,selectedWorldVersions} from '../domain/world-dynamics/tasks.js';
import {sameTarget} from '../domain/memory/repository.js';
import {createCalendar} from '../domain/time/calendar.js';
import {upcomingItems} from '../domain/time/occurrence.js';
import {cleanSummaryFloors} from '../domain/summary/cleaning.js';
import {defaultWorldConfig,assembleWorldRequest,worldResultText,worldDateText} from '../domain/world-dynamics/prompts.js';
import {assertWorldConfig,retainWorldVersions,worldCalendar} from '../domain/world-dynamics/data.js';
import {parseWorldOutput,validateWorldEntry} from '../domain/world-dynamics/output.js';
const copy=structuredClone,equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
export function createWorldDynamicsController({repository,captureSource,books,provider,settings,getContext=()=>({}),allowed=()=>true,onTime=()=>{},onManage=()=>{},id=()=>crypto.randomUUID(),now=()=>new Date().toISOString()}={}){
 let target=null,serial=0,disposed=false,prepared=null,requestAbort=null,bookOriginal=null,unconfirmed=false,generationPromise=null,entryOrigin=null;
 let state={route:'world',status:'loading',domain:null,time:null,config:null,draft:null,consoleOpen:{},bookList:[],bookPurpose:'worldRefs',entry:null,entryText:'',error:'',busy:false,waitVisible:false,request:null};
 const listeners=new Set(),notify=()=>{if(!disposed)for(const listener of listeners)try{listener(copy(state));}catch{}};
 const current=(t=target,s=serial)=>{try{return !disposed&&!unconfirmed&&s===serial&&sameTarget(t,repository.captureTarget())&&allowed();}catch{return false;}};
 const fail=error=>{if(error?.code==='COMMIT_UNCONFIRMED'||/尚未确认|待确认|可能已经保存/.test(error?.message??'')){unconfirmed=true;state.status='failed';}state.error=error?.message??'世界动态操作未完成';notify();return false;};
 function clearPreview(){prepared=null;state.request=null;}
 async function load(){if(state.busy)return false;const next=repository.captureTarget();if(!sameTarget(target,next)){requestAbort?.abort();serial++;target=copy(next);state={...state,route:'world',draft:null,entry:null,busy:false,waitVisible:false};}const t=copy(target),n=serial;state.status='loading';notify();try{const result=await repository.captureWorldDynamics(t);if(disposed||n!==serial||!sameTarget(t,repository.captureTarget()))return false;unconfirmed=false;state.domain=copy(result.worldDynamics);state.time=copy(result.time);{const migrated=modularWorldConfig(result.worldDynamics.config??defaultWorldConfig());state.config=migrated.config;state.error=migrated.error;}state.status='ready';state.route='world';clearPreview();notify();return true;}catch(error){state.status='failed';return fail(error);}}
 async function persist(apply,guard=()=>true){const t=copy(target),n=serial;if(!current(t,n))throw new Error('请重新读取世界动态');const receipt=await repository.updateWorldDynamics(t,{apply,isCurrent:()=>current(t,n)&&guard()});if(!current(t,n))throw new Error('聊天已变化');if(!['committed','unchanged'].includes(receipt.status))throw new Error('世界动态保存尚未确认');state.domain=copy(receipt.selection.worldDynamics);state.config=modularWorldConfig(state.domain.config??defaultWorldConfig()).config;return receipt;}
 function openConsole(){if(state.status!=='ready')return;state.consoleOpen={};state.draft=copy(state.config);state.route='console';state.error='';clearPreview();notify();}
 function section(key){if(!state.draft)state.draft=copy(state.config);state.consoleOpen[key]=true;state.route='console';notify();}
 function back(save=false){if(state.route==='books'){if(!save)state.draft=bookOriginal;state.route='console';state.consoleOpen.materials=true;}else if(state.route==='preview'){state.route=state.draft?'console':'world';}else if(state.route==='entry'){state.route='world';state.entry=null;}else if(state.route==='console'){state.draft=null;clearPreview();state.route='world';onManage();}else onTime();state.error='';notify();}

 function edit(path,value){if(unconfirmed||!state.draft)return;const keys=path.split('.');let node=state.draft;for(const key of keys.slice(0,-1)){if(!Object.hasOwn(node,key))return;node=node[key];}node[keys.at(-1)]=value;if(!state.busy)clearPreview();}
 async function saveConfig(){try{const config=assertWorldConfig(modularWorldConfig(state.draft).config);await persist(domain=>({...domain,config}));state.draft=null;state.route='world';state.error='';clearPreview();notify();onManage();return true;}catch(error){return fail(error);}}
 async function chooseBooks(purpose){if(!state.draft)return;state.bookPurpose=purpose;state.consoleOpen.materials=true;bookOriginal=copy(state.draft);state.route='books';state.bookList=[];state.error='';notify();const t=copy(target),n=serial;try{const list=await books.list();if(!current(t,n)||state.route!=='books')return false;state.bookList=copy(list);notify();return true;}catch(error){return current(t,n)?fail(error):false;}}
 function toggleRef(book,uid,checked){const refs=state.draft?.[state.bookPurpose];if(!refs)return;const ref={book,uid};state.draft[state.bookPurpose]=checked?[...refs.filter(r=>!equal(r,ref)),ref]:refs.filter(r=>!equal(r,ref));if(!state.busy)clearPreview();}
 function sourceMatches(t,raw){try{if(!current(t))return false;const next=captureSource(t);if(next.epoch!==raw.epoch||next.messages.length<raw.messages.length)return false;return raw.messages.every((m,i)=>equal(m,next.messages[i]));}catch{return false;}}
 async function prepare(){if(state.busy||!current())return false;const t=copy(target),n=serial,c=copy(state.draft??state.config);state.error='';state.status='preparing';notify();try{
   assembleWorldRequest(c,{});
   const result=await repository.captureWorldDynamics(t);if(!current(t,n))return false;const time=result.time,definition=time.calendars.find(row=>row.id===time.activeCalendarId);if(!definition||time.currentDate?.day==null)throw new Error('请先在时间管理中记录完整故事日期');const calendar=createCalendar(definition),date=calendar.validate(time.currentDate),raw=copy(captureSource(t)),endFloor=raw.messages.at(-1)?.floor??-1;
   const [world,characters]=await Promise.all([books.read(c.worldRefs),books.read(c.characterRefs)]);if(!current(t,n)||!sourceMatches(t,raw))throw new Error('聊天来源已变化，请重新准备');
   const previous=result.worldDynamics.current,selected=selectedWorldVersions(result.worldDynamics,c),first=previous===null,start=first?(c.initialScope==='recent'?Math.max(0,endFloor-c.initialCount+1):0):previous.endFloor+1;
   const generation=settings.getGenerationSettings();const floors=c.readStory?cleanSummaryFloors(raw.messages.filter(m=>m.floor>=start&&m.floor<=endFloor&&m.role!=='system'),{includeUser:true,rules:generation.summaryCleaning?.rules??[]}):[];
   const holidays=upcomingItems(calendar,time.items.filter(row=>row.kind==='holiday'),date).map(row=>`${row.title}｜${worldDateText(row.start)}｜${row.description??''}`).join('\n');
   const texts={LTcurrentDate:worldDateText(date),LTworldInfo:world.map(row=>`${row.book} / ${row.name}\n${row.content}`).join('\n\n')+(c.extra?'\n\n补充资料：\n'+c.extra:''),LTcharacterInfo:characters.map(row=>`${row.name}\n${row.content}`).join('\n\n')+(c.extraPeople?'\n补充人物：'+c.extraPeople:''),LTfestivalInfo:holidays,LTplotHistory:selected.filter(v=>v.kind==='plot').flatMap(v=>v.entries).map(e=>e.text).join('\n\n'),LTworldHistory:selected.filter(v=>v.kind!=='plot').map(v=>`故事日期：${worldDateText(v.version.date)}\n`+worldResultText({...v.version,entries:v.entries})).join('\n\n')+(result.worldDynamics.deleted.length?'\n\n用户已放弃以下安排，请勿原样补回：\n'+result.worldDynamics.deleted.filter(e=>taskEnabled(c,e.kind)).map(e=>e.text).join('\n\n'):''),LTstoryContext:floors.map(m=>`第${m.floor}楼\n${m.text}`).join('\n\n'),LTuserNotes:c.notes};
   const ctx=getContext(),request=assembleWorldRequest(c,texts);request.messages=request.messages.map(m=>({...m,content:m.content.replaceAll('{{user}}',ctx.name1??'用户').replaceAll('{{char}}',ctx.name2??'角色')}));
   const anchor=raw.messages.at(-1);prepared={target:t,raw,request,config:c,date,calendar:copy(definition),endFloor,anchor:anchor?{floor:anchor.floor,identity:anchor.identity,role:anchor.role,swipeId:anchor.swipeId??null}:null};state.request=copy(request);state.route='preview';state.status='ready';notify();return true;
  }catch(error){state.status='ready';return current(t,n)?fail(error):false;}}
 async function runGeneration(){if(state.busy||unconfirmed)return false;if(!prepared&&!await prepare())return false;const p=prepared,t=p.target,n=serial;if(!current(t,n)||!equal(p.config,state.draft??state.config)||!sourceMatches(t,p.raw)||captureSource(t).messages.length!==p.raw.messages.length){clearPreview();return fail(new Error('预览资料已变化，请重新准备'));}
   state.busy=true;state.waitVisible=true;state.error='';notify();requestAbort=new AbortController();const signal=requestAbort.signal,valid=()=>!signal.aborted&&current(t,n)&&sourceMatches(t,p.raw);
   try{const output=await provider.generateText({...copy(p.request),maxOutputTokens:8192,signal,isCurrent:valid});if(!valid())throw new Error('聊天来源已变化，本次结果未保存');const entries=parseWorldOutput(output.text,{calendar:p.calendar,date:p.date,config:p.config});const version={id:id(),date:copy(p.date),calendar:worldCalendar(p.calendar),entries,endFloor:p.endFloor,anchor:p.anchor,generatedAt:now()};
    await persist(domain=>{const retained={...domain.retained};for(const kind of Object.keys(WORLD_TASKS)){if(taskEnabled(p.config,kind))delete retained[kind];else if(domain.current?.entries.some(e=>e.kind===kind))retained[kind]={...copy(domain.current),entries:domain.current.entries.filter(e=>e.kind===kind)};}return {...domain,retained,current:version,versions:retainWorldVersions([...domain.versions,version],p.endFloor),deleted:domain.deleted.filter(e=>!taskEnabled(p.config,e.kind))};},valid);if(!valid())return false;state.route='world';state.draft=null;state.error='';clearPreview();return true;
   }catch(error){if(current(t,n))return fail(error);return false;}finally{if(!disposed&&n===serial){state.busy=false;state.waitVisible=false;requestAbort=null;notify();}}
 }
 async function saveEntry(remove=false){if(!state.entry||!entryOrigin)return false;const original=copy(state.entry),origin=copy(entryOrigin);try{const entry={...original,text:state.entryText.trim()};if(!remove)validateWorldEntry(entry,origin.calendar,origin.date);await persist(domain=>{
   const version=origin.retained?domain.retained?.[original.kind]:domain.current;
   if(version?.id!==origin.id||!equal(version.entries.find(e=>e.id===original.id),original))throw new Error('世界成果已变化，请重新打开');
   const patch=v=>({...v,entries:remove?v.entries.filter(e=>e.id!==entry.id):v.entries.map(e=>e.id===entry.id?entry:e)});
   return {...domain,current:!origin.retained?patch(domain.current):domain.current,retained:origin.retained?{...domain.retained,[original.kind]:patch(version)}:domain.retained,versions:domain.versions.map(v=>v.id===origin.id?patch(v):v),deleted:remove?[...domain.deleted,{kind:original.kind,text:original.text}]:domain.deleted};
  });state.entry=null;entryOrigin=null;state.route='world';clearPreview();notify();return true;}catch(error){return fail(error);}}

 function generate(){if(generationPromise)return generationPromise;const job=runGeneration();generationPromise=job;void job.finally(()=>{if(generationPromise===job)generationPromise=null,entryOrigin=null;}).catch(()=>{});return job;}
 return Object.freeze({load,ensure:()=>current()&&state.status==='ready'?Promise.resolve(true):load(),inspect:()=>copy(state),subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},openConsole,section,back,edit,saveConfig,chooseBooks,toggleRef,prepare,generate,saveEntry,openEntry(entryId){const selected=selectedWorldVersions(state.domain,state.config).find(v=>v.entries.some(e=>e.id===entryId));const entry=selected?.entries.find(e=>e.id===entryId);if(!entry)return;entryOrigin={id:selected.version.id,date:copy(selected.version.date),calendar:copy(selected.version.calendar),retained:selected.version!==state.domain.current};state.entry=copy(entry);state.entryText=entry.text;state.route='entry';state.error='';notify();},editEntry(text){state.entryText=text;},refresh(){notify();},setOpen(key,value){state.consoleOpen[key]=!!value;},toggle(path,silent=false){const keys=path.split('.');let node=state.draft;for(const key of keys.slice(0,-1))node=node[key];edit(path,!node[keys.at(-1)]);if(!silent)notify();},addIdea(){state.draft.ideas.push({id:id(),name:'',content:'',enabled:true});clearPreview();notify();},removeIdea(index){state.draft.ideas.splice(index,1);clearPreview();notify();},dismissWait(){state.waitVisible=false;notify();},cancel(){requestAbort?.abort();},dispose(){disposed=true;serial++;requestAbort?.abort();listeners.clear();prepared=null;},invalidate(){serial++;requestAbort?.abort();clearPreview();state.busy=false;state.waitVisible=false;state.status='failed';state.error='聊天已变化，请重新读取';notify();}});
}
